def _hashable_repr(k):
    """Best-effort canonical, hashable representation of a (possibly
    unhashable) key, used as the fast-path membership token.

    Two keys with equal values get the same token, so collisions among
    *unequal* keys are possible -- callers must still confirm matches
    with ``==``.
    """
    t = type(k)
    if t is dict:
        return (
            "d",
            tuple(sorted((t for t in _hashable_repr(key)),
                         key=repr)) if isinstance(k, str)
            else _dict_repr(k),
        )
    if t is list:
        return ("l",) + tuple(_hashable_repr(v) for v in k)
    if t is tuple:
        return ("t",) + tuple(_hashable_repr(v) for v in k)
    if t is set:
        return ("s",) + tuple(sorted((_hashable_repr(v),) for v in k),
                              key=repr)
    return ("h", hash(k), t, k)


def _dict_repr(k):
    return tuple((key, _hashable_repr(value))
                 for key, value in sorted(k.items(),
                                          key=lambda item: repr(item[0])))


def dedupe(records, key=None):
    seen = set()
    unhashable = []
    out = []
    for r in records:
        k = key(r) if key else r
        try:
            h = hash(k)
        except TypeError:
            if not any(k == s for s in unhashable):
                unhashable.append(k)
                out.append(r)
        else:
            if h not in seen:
                # Same hash may belong to an unequal key with an equal
                # hash; confirm with == before treating it as new.
                if not any(h == s and k == s for s in seen):
                    seen.add(k)
                    out.append(r)
    return out
