{"path":"etl/dedupe.py","content":""""Remove duplicate records, keeping the first occurrence.

The fast path is a hash set: each key is checked with O(1) membership.
Keys that are not directly hashable (e.g. lists or dicts, which is what
records look like when no ``key`` function is given, and what custom
``key`` functions may return) are handled with a linear scan, so the
result is still exactly "keep the first record whose key equals none
of the earlier keys".
"""

# Sentinel: a key is in ``seen`` iff this is what _try_add returns when it
# is already present.
_PRESENT = object()


def _normalize(k):
    """Convert a (possibly unhashable) key into a hashable token that
    collides only between keys that are also equal under ``==`` for the
    common JSON-like types (dict, list).

    Used purely to pick which of the fast path (hash set) or the slow
    path (linear list of unhashable keys) a key belongs to; equality
    itself is always decided by ``==``.
    """
    t = type(k)
    if t is dict:
        return ("d",) + tuple(
            sorted(((key, _normalize(value)) for key, value in k.items()),
                   key=repr)
        )
    if t is list:
        return ("l",) + tuple(_normalize(v) for v in k)
    return k


def _try_add(seen, k):
    """Add k to ``seen`` unless it already equals a member; return True
    if it was added."""
    for s in seen:
        if s is k or s == k:
            return False
    seen.append(k)
    return True


def dedupe(records, key=None):
    hashable_seen = set()
    unhashable_seen = []
    out = []
    for r in records:
        k = key(r) if key else r
        try:
            h = hash(k)
        except TypeError:
            if _try_add(unhashable_seen, k):
                out.append(r)
        else:
            if h not in hashable_seen:
                # A different key can share this hash; confirm with ==.
                if not any(k is s or k == s for s in hashable_seen
                           if hash(s) == h):
                    hashable_seen.add(k)
                    out.append(r)
    return out
"}

