{"path":"etl/dedupe.py","content":""""Remove duplicate records, keeping the first occurrence.

Equality is decided by ``==`` exactly as before; this module only makes
membership checks fast.  Directly hashable keys go into a set (O(1)).
Unhashable keys (records are dicts; custom ``key`` functions may return
lists or dicts) go through a two-level structure:

* ``unhashable_seen`` -- the list of accepted unhashable keys, the
  ground truth; a new key is a duplicate iff it ``==``-compares equal to
  some element.
* ``candidates`` -- a set of normalized, hashable tokens.  The
  normalization collides only between keys that are also ``==``-equal
  for the JSON-like types it understands (dicts compare key-insensitive
  to order, lists positionally, anything else by ``(hash, type, value)``
  with the value itself used only for the final ``==`` check).  A key
  whose candidate is absent is definitely new (append + insert token);
  a present candidate means "scan the list before deciding".
"""


def _token(k):
    """A hashable token for a possibly unhashable key.  Tokens of two
    keys are equal only when the keys are ``==``-equal (for dict/list/
    tuple/set and plain values); the converse can fail on exotic
    collisions, which the caller resolves with a ``==`` scan."""
    t = type(k)
    if t is dict:
        return ("d",) + tuple(sorted(
            ((repr(key), _token(key), _token(value))
             for key, value in k.items()), key=itemgetter0))
    if t is list:
        return ("l",) + tuple(_token(v) for v in k)
    if t is tuple:
        return ("t",) + tuple(_token(v) for v in k)
    if t is set:
        return ("s",) + tuple(sorted((_token(v),) for v in k),
                              key=repr)
    return ("h", hash(k), t, k)


def itemgetter0(item):
    return item[0]


def _token_of(k):
    # wrapper to keep _token's dict branch readable
    return _token(k)


def _try_add_unhashable(unhashable_seen, candidates, k):
    token = _token(k)
    if token not in candidates:
        # Definitely unseen.
        unhashable_seen.append(k)
        candidates.add(token)
        return True
    # Candidate may be an equal key (typical) or a token collision
    # between unequal keys (rare); decide with ==.
    if any(k == s for s in unhashable_seen):
        return False
    unhashable_seen.append(k)
    candidates.add(token)
    return True


def dedupe(records, key=None):
    hashable_seen = set()
    unhashable_seen = []
    unhashable_candidates = set()
    out = []
    for r in records:
        k = key(r) if key else r
        try:
            hash(k)
        except TypeError:
            if _try_add_unhashable(unhashable_seen, unhashable_candidates, k):
                out.append(r)
        else:
            if k not in hashable_seen:
                hashable_seen.add(k)
                out.append(r)
    return out
"}

