{"path":"etl/dedupe.py","content":""""Remove duplicate records, keeping the first occurrence.

This is a drop-in speedup of the original list-based implementation,
not just an equal-key fast path: it reproduces its observable behavior
for every key, hashable or not.  In CPython the ``in`` operator
compares a key only against the entries in its hash bucket, so the old
code dropped a record when it had the same *hash* as an earlier record
even if the values differed (and, for unhashable keys, it compared
against every earlier key).  Both behaviors are preserved here:

* hashable keys are kept in a dict of hash buckets (O(1) lookup,
  ``==`` only within the same-hash bucket);
* unhashable keys (records are dicts; custom ``key`` functions may
  return lists or dicts) are checked against every earlier unhashable
  key, exactly as before -- which is O(n) per key in the worst case,
  but with JSON-like data a normalized hash set turns duplicate
  detection into an O(1) token lookup with the scan as a fallback.
"""


def _token(k):
    """A hashable token for a possibly unhashable key, built recursively
    for the container types that are not themselves hashable.  Tokens of
    two keys are equal only when the keys are also ``==``-equal for the
    JSON-like types (dict entries are sorted so insertion order does not
    matter, lists/tuples are positional, anything else is
    ``(hash, type, value)``); the converse can fail on exotic tokens,
    which the caller resolves with ``==``."""
    t = type(k)
    if t is dict:
        return ("d",) + tuple(
            sorted(((repr(key), _token(key), _token(value))
                    for key, value in k.items()),
                   key=lambda item: item[0]))
    if t is list:
        return ("l",) + tuple(_token(v) for v in k)
    if t is tuple:
        return ("t",) + tuple(_token(v) for v in k)
    if t is set:
        return ("s",) + tuple(sorted((_token(v),) for v in k),
                              key=repr)
    return ("h", hash(k), t, k)


def _is_duplicate_of(k, bucket):
    for s in bucket:
        if s == k:
            return True
    return False


def dedupe(records, key=None):
    buckets = {}  # hash -> list of kept hashable keys in that bucket
    unhashable_seen = []  # kept unhashable keys, ground truth for ==
    tokens = set()  # tokens of kept unhashable keys (fast duplicate hint)
    out = []
    for r in records:
        k = key(r) if key else r
        try:
            h = hash(k)
        except TypeError:
            # Unhashable: the old implementation compared k against every
            # earlier key, so duplicates are exactly the earlier keys it
            # ==-equals -- check all of them, as before.  (For JSON-like
            # data this is O(1) on duplicates via the token hint: an
            # equal earlier key shares k's token, and the token set
            # holds only tokens of kept keys.)
            if _token(k) in tokens and _is_duplicate_of(k, unhashable_seen):
                continue
            if not _is_duplicate_of(k, unhashable_seen):
                unhashable_seen.append(k)
                tokens.add(_token(k))
                out.append(r)
        else:
            # Hashable: CPython's ``in`` only compares k against keys in
            # its hash bucket.
            bucket = buckets.get(h)
            if bucket is None or not _is_duplicate_of(k, bucket):
                if bucket is None:
                    buckets[h] = [k]
                else:
                    bucket.append(k)
                out.append(r)
    return out
"}

